#!/usr/bin/env node
/*
 * Simple security scanner for Node.js applications
 * Checks for common security issues in JavaScript files
 */

const fs = require('fs');
const path = require('path');

// Patterns to check for potential security issues
const patterns = [
  {
    name: 'Hardcoded credentials',
    regex: /(password|passwd|pwd|secret|key|token|credential)s?\s*[:=]\s*["'][^"'\s]+["']/gi,
    description: 'Potential hardcoded credentials found',
    severity: 'high'
  },
  {
    name: 'AWS keys',
    regex: /(AKIA|access[_-]?key[_-]?id)[\s"':=]+[A-Z0-9]{16,}/i,
    description: 'Potential AWS access key found',
    severity: 'high'
  },
  {
    name: 'AWS secret keys',
    regex: /(secret[_-]?access[_-]?key)[\s"':=]+[A-Za-z0-9\/+=]{40,}/i,
    description: 'Potential AWS secret key found',
    severity: 'high'
  },
  {
    name: 'Stripe keys',
    regex: /(sk_live_|rk_live_)[a-zA-Z0-9]{24,}/i,
    description: 'Potential live Stripe key found',
    severity: 'high'
  },
  {
    name: 'Database URLs with credentials',
    regex: /(postgres|postgresql|mysql|mongodb):\/\/[^"\s']*:[^"\s']*@/i,
    description: 'Database URL with embedded credentials found',
    severity: 'high'
  },
  {
    name: 'API keys pattern',
    regex: /(api[_-]?key|apikey)\s*[:=]\s*["'][a-zA-Z0-9_\-]{20,}["']/i,
    description: 'Potential API key found',
    severity: 'medium'
  },
  {
    name: 'Eval usage',
    regex: /\beval\s*\(/,
    description: 'Use of eval() found - potential code injection risk',
    severity: 'high'
  },
  {
    name: 'SetTimeout with string',
    regex: /setTimeout\s*\(\s*["']/,
    description: 'setTimeout with string argument found - potential code injection',
    severity: 'medium'
  },
  {
    name: 'SetInterval with string',
    regex: /setInterval\s*\(\s*["']/,
    description: 'setInterval with string argument found - potential code injection',
    severity: 'medium'
  },
  {
    name: 'Function constructor with string',
    regex: /new\s+Function\s*\(\s*["']/,
    description: 'Function constructor with string found - potential code injection',
    severity: 'high'
  },
  {
    name: 'Express.js X-Powered-By',
    regex: /x-powered-by\s*[:=]/i,
    description: 'X-Powered-By header may be enabled - reveals technology stack',
    severity: 'low'
  },
  {
    name: 'Debug output in production',
    regex: /console\.(log|debug|info)\s*\(/i,
    description: 'Console output found - may leak sensitive information in production',
    severity: 'low'
  },
  {
    name: 'Regular expression DoS',
    regex: /\/\[^\]]*\\\/[gimuy]*\(|\/\^.*\$\//,
    description: 'Potentially dangerous regex pattern that could lead to ReDoS',
    severity: 'medium'
  }
];

// Files to exclude from scanning
const excludePatterns = [
  /node_modules/,
  /\.git/,
  /security-scan\.js$/,
  /\.env\.example$/,
  /package-lock\.json$/,
  /yarn-lock\.json$/
];

/**
 * Check if a file should be excluded from scanning
 * @param {string} filePath - Path to the file
 * @returns {boolean} - True if file should be excluded
 */
function shouldExclude(filePath) {
  return excludePatterns.some(pattern => pattern.test(filePath));
}

/**
 * Scan a file for security issues
 * @param {string} filePath - Path to the file to scan
 * @returns {Array} - Array of found issues
 */
function scanFile(filePath) {
  try {
    const content = fs.readFileSync(filePath, 'utf8');
    const issues = [];

    patterns.forEach(pattern => {
      let match;
      while ((match = pattern.regex.exec(content)) !== null) {
        // Calculate line number
        const lineNumber = content.substring(0, match.index).split('\n').length;

        issues.push({
          file: filePath,
          line: lineNumber,
          column: match.index - content.lastIndexOf('\n', match.index) - 1,
          pattern: pattern.name,
          description: pattern.description,
          severity: pattern.severity,
          match: match[0].substring(0, 100) // Limit match length for display
        });
      }
    });

    return issues;
  } catch (error) {
    console.error(`Error scanning file ${filePath}:`, error.message);
    return [];
  }
}

/**
 * Recursively scan a directory for JavaScript files
 * @param {string} dirPath - Path to the directory to scan
 * @returns {Array} - Array of found issues
 */
function scanDirectory(dirPath) {
  const issues = [];

  try {
    const entries = fs.readdirSync(dirPath, { withFileTypes: true });

    for (const entry of entries) {
      const fullPath = path.join(dirPath, entry.name);

      if (shouldExclude(fullPath)) {
        continue;
      }

      if (entry.isDirectory()) {
        issues.push(...scanDirectory(fullPath));
      } else if (entry.isFile() && 
                (entry.name.endsWith('.js') || 
                 entry.name.endsWith('.ts') ||
                 entry.name.endsWith('.jsx') ||
                 entry.name.endsWith('.tsx'))) {
        issues.push(...scanFile(fullPath));
      }
    }
  } catch (error) {
    console.error(`Error scanning directory ${dirPath}:`, error.message);
  }

  return issues;
}

/**
 * Main scanning function
 */
function main() {
  const startTime = Date.now();
  const directoryToScan = process.argv[2] || '.';

  console.log(`🔒 Starting security scan of ${directoryToScan}...\n`);

  const issues = scanDirectory(directoryToScan);

  if (issues.length === 0) {
    console.log('✅ No security issues found!');
    process.exit(0);
  }

  // Sort by severity
  const severityOrder = { high: 3, medium: 2, low: 1 };
  issues.sort((a, b) => 
    (severityOrder[b.severity] || 0) - (severityOrder[a.severity] || 0)
  );

  console.log(`🚨 Found ${issues.length} potential security issues:\n`);

  let highCount = 0;
  let mediumCount = 0;
  let lowCount = 0;

  issues.forEach((issue, index) => {
    const severityIcon = issue.severity === 'high' ? '🔴' :
                        issue.severity === 'medium' ? '🟡' : '🟢';

    console.log(`${severityIcon} [${issue.severity.toUpperCase()}] ${issue.pattern}`);
    console.log(`   File: ${issue.file}`);
    console.log(`   Line: ${issue.line + 1}, Column: ${issue.column + 1}`);
    console.log(`   Description: ${issue.description}`);
    console.log(`   Match: ${issue.match}\n`);

    if (issue.severity === 'high') highCount++;
    else if (issue.severity === 'medium') mediumCount++;
    else lowCount++;
  });

  console.log(`📊 Summary:`);
  console.log(`   🔴 High: ${highCount}`);
  console.log(`   🟡 Medium: ${mediumCount}`);
  console.log(`   🟢 Low: ${lowCount}`);
  console.log(`   ⏱️  Scan completed in ${(Date.now() - startTime) / 1000}s\n`);

  if (highCount > 0) {
    console.log('❌ Security scan failed - high severity issues found');
    process.exit(1);
  } else if (mediumCount > 0) {
    console.log('⚠️  Security scan completed - medium severity issues found (review recommended)');
    process.exit(0);
  } else {
    console.log('✅ Security scan passed');
    process.exit(0);
  }
}

// Run the scanner if this file is executed directly
if (require.main === module) {
  main();
}

module.exports = { scanFile, scanDirectory };

